import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Router } from '@angular/router';
import { ApiService } from '../api.service';

@Component({
  selector: 'app-dashboard',
  standalone: true,
  imports: [CommonModule],
  template: `
    <div class="container">
      <div class="card">
        <h1>SmartOptions Dashboard</h1>
        <p>Welcome to your options trading platform</p>

        <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 20px; margin-top: 30px;">

          <div class="card">
            <h3>Strategy Builder</h3>
            <p>Create and analyze options strategies</p>
            <button class="btn" (click)="goToStrategyBuilder()">Build Strategy</button>
          </div>

          <div class="card">
            <h3>API Documentation</h3>
            <p>Interactive API testing and documentation</p>
            <a href="http://localhost:8000/swagger/" target="_blank">
              <button class="btn">Open Swagger UI</button>
            </a>
          </div>

          <div class="card">
            <h3>Admin Panel</h3>
            <p>Manage system settings and data</p>
            <a href="http://localhost:8000/admin/" target="_blank">
              <button class="btn btn-secondary">Admin Panel</button>
            </a>
          </div>

        </div>

        <div class="card" style="margin-top: 20px;">
          <h3>Your Strategies</h3>
          <div *ngIf="strategies.length === 0">
            <p>No strategies created yet. <a href="#" (click)="goToStrategyBuilder()">Create your first strategy</a></p>
          </div>
          <div *ngFor="let strategy of strategies" class="card">
            <h4>Strategy #{{ strategy.id }}</h4>
            <p>Expected Profit: {{ strategy.expected_profit || 'N/A' }}</p>
            <p>Expected Loss: {{ strategy.expected_loss || 'N/A' }}</p>
          </div>
        </div>

      </div>
    </div>
  `
})
export class DashboardComponent implements OnInit {
  strategies: any[] = [];

  constructor(private apiService: ApiService, private router: Router) {}

  ngOnInit() {
    this.loadStrategies();
  }

  loadStrategies() {
    this.apiService.getStrategies().subscribe({
      next: (data) => this.strategies = data,
      error: (error) => console.error('Error loading strategies:', error)
    });
  }

  goToStrategyBuilder() {
    this.router.navigate(['/strategy-builder']);
  }
}
